// Des: Replay an owner-captured request (HAR or curl) and store the reply
// Flo: read spec file > fill {params} > send with deadline through the host guard > 401/403 = stale signature > save by hidden-secret URL > print outcome
// I/O: --spec file + --param k=v (caller) > page record; errors BadSpec PinBypass StaleSpec; never logs headers or cookies
// ===================================================================
const std = @import("std"); const spec = @import("pa-spec-read.zig"); const fspc = @import("nt-fetc-spec.zig"); const pipe = @import("ru-page-fetc.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const urln = @import("ut-urlz-norm.zig"); const cx = @import("ct-ctrl-ctxz.zig"); const exit = @import("ct-exit-code.zig");
pub fn replay(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Db, dirz: []const u8, text: []const u8, parm: []const u8, priv: bool) !pipe.Outc { const raw = try spec.specRead(aren, text); const spc = try spec.specFill(aren, raw, parm); _ = urln.urlSplit(spc.urlz) catch return error.BadSpec; const resp = try fspc.specFetc(gpaz, aren, iozz, spc, .{ .time_mill = conf.fetc_time_seco * 1000, .body_maxz = conf.fetc_body_maxz, .priv = priv }); if (resp.code == 401 or resp.code == 403) return error.StaleSpec; if (resp.code == 429) return error.Blocked; const key = try urln.urlNorm(aren, try spec.urlSafe(aren, spc.urlz)); const prev = try inde.pageGet(dbzz, aren, key); return pipe.pageSave(aren, iozz, conf, dbzz, dirz, key, prev, .{ .code = resp.code, .ctyp = resp.ctyp, .body = resp.body }); }
pub fn runRepl(ctx: *const cx.Ctx) !u8 { if (ctx.args.spec.len == 0) return error.BadUsage; const text = std.Io.Dir.cwd().readFileAlloc(ctx.iozz, ctx.args.spec, ctx.allo, .limited(4 << 20)) catch return error.BadUsage; const spc = try spec.specFill(ctx.allo, try spec.specRead(ctx.allo, text), ctx.args.parm); const part = urln.urlSplit(spc.urlz) catch return error.BadSpec; if (!ctx.args.live) { try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "dry-run | replay {s} https://{s}/... | {d} headers, body {d} bytes | own IP, no vendor, no spend | add --live to send", .{ spc.meth, part.host, spc.hdrs.len, spc.body.len })); return 0; } var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); const outc = try replay(ctx.init.gpa, ctx.allo, ctx.iozz, ctx.conf, &dbzz, ctx.dirz, text, ctx.args.parm, false); const plain = try std.fmt.allocPrint(ctx.allo, "{s} | {d} | {s} | {s} | {s}", .{ outc.stat, outc.code, outc.kind, outc.urlz, outc.hexz }); try cx.outz(ctx, try cx.jsonOr(ctx, outc, plain)); return exit.outcCode(outc.stat, outc.code); }
